import { useGLTF } from "@react-three/drei";
import { useThree } from "@react-three/fiber";
import { assetUrl } from "../../lib/assetUrl";
import { extendGltf } from "./gltfExtensions";

// Generated by tools/city3/roadmarks.py: lane/edge/stop-line paint and symbolic warning signs (static, no animation).
const MODEL = assetUrl("/assets/world-roadmarks.glb");

/** Horizontal road paint and vertical signs at the Bazaar streets and junctions. */
export function RoadMarks() {
  const gl = useThree((s) => s.gl);
  const gltf = useGLTF(MODEL, true, true, extendGltf(gl));
  return <primitive object={gltf.scene} />;
}
